insert into public.learning_cards (lesson_id, position, title, blocks) values ('5fcb34e4-a51d-5ba0-bb95-c64bf0668315', 1, 'Bip, bip', '[{"type":"keyfigure","value":"1957","label":"Lancement de Spoutnik 1, premier satellite"},{"type":"text","text":"Le 4 octobre 1957, une petite sphère soviétique émet des « bips » depuis l’orbite. La course à l’espace est lancée. En novembre, la chienne Laïka devient le premier animal en orbite."}]'::jsonb);
insert into public.learning_cards (lesson_id, position, title, blocks) values ('5fcb34e4-a51d-5ba0-bb95-c64bf0668315', 2, 'Gagarine', '[{"type":"text","text":"Le 12 avril 1961, Youri Gagarine fait le tour de la Terre à bord de Vostok 1. Il est le premier humain dans l’espace."}]'::jsonb);
insert into public.learning_cards (lesson_id, position, title, blocks) values ('5fcb34e4-a51d-5ba0-bb95-c64bf0668315', 3, 'D’autres premières', '[{"type":"list","items":["1963 : Valentina Terechkova, première femme dans l’espace.","1965 : Alexeï Leonov, première sortie dans le vide spatial."]}]'::jsonb);
