insert into public.learning_cards (lesson_id, position, title, blocks) values ('2266f03c-7bb7-55c2-bba4-7c7f1d8a4d6c', 1, 'Un petit pas', '[{"type":"text","text":"En juillet 1969, Neil Armstrong pose le pied sur la Lune : « C’est un petit pas pour l’homme, un bond de géant pour l’humanité. » Buzz Aldrin le rejoint, Michael Collins reste en orbite."}]'::jsonb);
insert into public.learning_cards (lesson_id, position, title, blocks) values ('2266f03c-7bb7-55c2-bba4-7c7f1d8a4d6c', 2, 'Douze hommes', '[{"type":"keyfigure","value":"12","label":"Astronautes ayant marché sur la Lune, entre 1969 et 1972"},{"type":"text","text":"Tous sont américains. Apollo 17, en 1972, est la dernière mission habitée sur la Lune."}]'::jsonb);
insert into public.learning_cards (lesson_id, position, title, blocks) values ('2266f03c-7bb7-55c2-bba4-7c7f1d8a4d6c', 3, 'Houston, on a un problème', '[{"type":"text","text":"En 1970, une explosion endommage Apollo 13. L’équipage contourne la Lune sans s’y poser et rentre sain et sauf."}]'::jsonb);
