insert into public.learning_cards (lesson_id, position, title, blocks) values ('93950431-92af-502e-a6f5-ce36169c5c8d', 1, 'Une maison en orbite', '[{"type":"text","text":"La Station spatiale internationale est habitée en permanence depuis 2000. Elle vole à environ 400 km d’altitude et fait le tour de la Terre en 90 minutes environ : ses occupants voient environ 16 levers de soleil par jour."}]'::jsonb);
insert into public.learning_cards (lesson_id, position, title, blocks) values ('93950431-92af-502e-a6f5-ce36169c5c8d', 2, 'Les Français', '[{"type":"list","items":["1982 : Jean-Loup Chrétien, premier Français dans l’espace.","1996 : Claudie Haigneré, première Française.","2016 puis 2021 : Thomas Pesquet séjourne dans l’ISS."]}]'::jsonb);
insert into public.learning_cards (lesson_id, position, title, blocks) values ('93950431-92af-502e-a6f5-ce36169c5c8d', 3, 'Départ de Guyane', '[{"type":"text","text":"Les fusées européennes Ariane décollent de Kourou, en Guyane française. Sa position proche de l’équateur aide les fusées à prendre de la vitesse."}]'::jsonb);
