insert into public.learning_cards (lesson_id, position, title, blocks) values ('d558489f-67ad-5f2b-87f8-fbda608541eb', 1, 'Huit, pas neuf', '[{"type":"keyfigure","value":"8","label":"Planètes dans le système solaire"},{"type":"text","text":"Mercure, Vénus, la Terre, Mars, Jupiter, Saturne, Uranus et Neptune. Pluton a été reclassée en planète naine en 2006."}]'::jsonb);
insert into public.learning_cards (lesson_id, position, title, blocks) values ('d558489f-67ad-5f2b-87f8-fbda608541eb', 2, 'Les records', '[{"type":"list","items":["Mercure : la plus proche du Soleil.","Vénus : la plus chaude, à cause de son atmosphère épaisse.","Jupiter : la plus grande.","Saturne : la plus célèbre pour ses anneaux."]}]'::jsonb);
insert into public.learning_cards (lesson_id, position, title, blocks) values ('d558489f-67ad-5f2b-87f8-fbda608541eb', 3, 'Les distances', '[{"type":"text","text":"La lumière du Soleil met environ 8 minutes pour nous parvenir. La Lune, elle, est à environ 384 000 km."}]'::jsonb);
